import{_ as o,o as a,c as i,a2 as t}from"./chunks/framework.Buc7gXeZ.js";const h=JSON.parse('{"title":"API 概览","description":"MusicBrainz WS/2 风格的开放 API：Lookup / Browse / Search 与 OpenAPI。","frontmatter":{"title":"API 概览","description":"MusicBrainz WS/2 风格的开放 API：Lookup / Browse / Search 与 OpenAPI。","order":30,"group":"api"},"headers":[],"relativePath":"api-overview.md","filePath":"api-overview.md"}'),d={name:"api-overview.md"};function c(s,e,r,l,n,p){return a(),i("div",null,[...e[0]||(e[0]=[t('<div class="warning custom-block"><p class="custom-block-title">文档与实现存在差异（一手提示）</p><p>MetaFusion <strong>不是</strong> MusicBrainz WS/2 风格 API，下列本页提及的端点/参数在当前实现中<strong>并不存在</strong>：</p><ul><li><code>GET /api/ws/2/*</code>（WS/2 兼容层从未实现）</li><li><code>GET /api/search</code>（现为 <code>GET /api/catalog/entities?q=...</code>，服务端为 PostgreSQL 模糊/全文匹配）</li><li><code>GET /api/browse/*</code>（现为 <code>GET /api/catalog/entities?kind=...&amp;&lt;关联 id 过滤&gt;</code>）</li><li><code>POST /api/auth/tokens</code>（PAT 管理端点缺失；当前仅有会话 Cookie + Bearer）</li><li><code>GET /api/catalog/works</code>、<code>GET /api/catalog/works/:id</code>、<code>/works/:id/graph</code>、<code>/catalog/taxonomy</code>、<code>/catalog/relation-types</code>、<code>/catalog/artists/:id</code>、<code>/catalog/franchises/:id</code>、<code>/catalog/mediums/:id</code>、<code>/catalog/canonical-entries/:id</code>（旧兼容层已删除，统一走 <code>/api/catalog/entities</code> 系）</li><li><code>inc=artists+releases+...</code> 展开参数与 <code>page</code> / <code>page_size</code> 分页（现为 <code>limit</code> / <code>offset</code> 与各实体独立字段）</li><li><code>catalog</code> 写入并非 RESTful 逐实体端点，统一为 <code>POST|PUT /api/catalog/entities</code></li></ul><p><strong>真实主干</strong>：读 <code>GET /api/catalog/definitions</code>、<code>/api/catalog/entities</code>、<code>/api/catalog/entities/:id</code>、<code>/api/catalog/entities/:id/relations|revisions|occurrences</code>、<code>/api/catalog/compare</code>、<code>/api/catalog/tags</code>（标签频次聚合）、<code>/api/catalog/shelves</code>、<code>/api/catalog/external-databases</code>；写 <code>POST /api/catalog/entities</code>、<code>PUT /api/catalog/entities/:id</code>、<code>POST /api/catalog/relations</code>、<code>PUT|DELETE /api/catalog/relations/:id</code>、<code>POST /api/catalog/entities/:id/lifecycle</code>；收藏 <code>POST /api/favorites/toggle</code>、<code>GET /api/favorites/status</code>、<code>GET /api/favorites/mine</code>、<code>GET /api/users/:id/favorites</code>；导入 <code>POST /api/importer/preview</code>、<code>POST /api/importer/import</code>；认证 <code>/api/setup</code>、<code>/api/auth/*</code>、<code>/api/oauth/*</code>。以 <a href="/docs/api/openapi.json">OpenAPI</a> 与 <code>backend/internal/catalog/http.go</code> 为准。</p></div><h1 id="api-概览" tabindex="-1">API 概览 <a class="header-anchor" href="#api-概览" aria-label="Permalink to &quot;API 概览&quot;">​</a></h1><p>MetaFusion 提供 MusicBrainz WS/2 风格的开放编目 API，适合自建应用与 Agent 接入。<strong>所有网页端功能均可经 API 复现。</strong></p><h2 id="基础信息" tabindex="-1">基础信息 <a class="header-anchor" href="#基础信息" aria-label="Permalink to &quot;基础信息&quot;">​</a></h2><ul><li><strong>Base URL</strong>：<code>/api</code>（网关统一透传至 <code>backend:8080</code>）</li><li><strong>OpenAPI 规范</strong>：<a href="/docs/api/openapi.json">GET /api/openapi.json</a>（OpenAPI 3.0.3 规范，含全量 Paths 与 Schemas）</li><li><strong>交互式文档中心</strong>：<a href="/docs/api/docs">Scalar 交互式参考 (/api/docs)</a> 与 <a href="/docs/api/swagger">Swagger UI (/api/swagger)</a></li><li><strong>认证</strong>：会话 Cookie（<code>mf_session</code>）或 <code>Authorization: Bearer &lt;session token&gt;</code>；<code>/api/oauth/*</code> 提供 OAuth 2.0 / OIDC 端点</li><li><strong>限流</strong>：仅在少数重型/敏感路由生效（如 <code>/api/catalog/entities</code> 120/min、<code>/api/catalog/compare</code> 10/min、<code>/api/setup</code> 与 <code>/api/auth/login</code> 防爆破），超限返回 429 + <code>Retry-After</code>。<strong>不存在全站 <code>X-RateLimit-*</code> 响应头</strong></li></ul><h2 id="能力分组" tabindex="-1">能力分组 <a class="header-anchor" href="#能力分组" aria-label="Permalink to &quot;能力分组&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>真实端点</th><th>认证</th></tr></thead><tbody><tr><td><strong>实体查询</strong></td><td><code>GET /api/catalog/entities</code>（<code>kind</code>/<code>q</code>/关联 id 过滤）</td><td>开放</td></tr><tr><td><strong>实体详情</strong></td><td><code>GET /api/catalog/entities/:id</code>、<code>/resolve</code>、<code>/relations</code>、<code>/occurrences</code>（收录按 kind：expression=自身，content_unit/work=其表达）、<code>/revisions</code></td><td>开放</td></tr><tr><td><strong>写入</strong></td><td>`POST</td><td>PUT /api/catalog/entities<code>、</code>/api/catalog/relations<code>、</code>/lifecycle`</td></tr><tr><td><strong>对比</strong></td><td><code>GET /api/catalog/compare?ids=a,b</code></td><td>开放</td></tr><tr><td><strong>收藏</strong></td><td><code>POST /api/favorites/toggle</code>、<code>GET /api/favorites/status</code>、<code>/api/favorites/mine</code>、<code>/api/users/:id/favorites</code></td><td>切换/自列需登录</td></tr></tbody></table><h2 id="访问模型" tabindex="-1">访问模型 <a class="header-anchor" href="#访问模型" aria-label="Permalink to &quot;访问模型&quot;">​</a></h2><ul><li><strong>元数据开放</strong>：<code>/api/catalog/*</code> 读接口无需鉴权，可被搜索引擎收录</li><li><strong>写入受控</strong>：实体/关系写入需登录，<code>lifecycle</code> 合并/退役需管理员；媒体二进制走可选 <code>archive</code> / <code>playback</code> 模块，强制登录</li></ul><h2 id="认证方式" tabindex="-1">认证方式 <a class="header-anchor" href="#认证方式" aria-label="Permalink to &quot;认证方式&quot;">​</a></h2><p>见 <a href="/docs/api-auth">认证与 PAT</a>：</p><ul><li><strong>会话</strong>：<code>POST /api/auth/login</code> 返回令牌并写入 HttpOnly Cookie <code>mf_session</code>（访问令牌 15 分钟有效，服务端会话兜底 24 小时；<code>POST /api/auth/refresh</code> 可换发新令牌）</li><li><strong>OAuth 2.0 / OIDC</strong>：<code>/api/oauth/authorize</code>、<code>/api/oauth/token</code>、<code>/api/oauth/userinfo</code></li></ul><p>凭证以 <code>Authorization: Bearer &lt;token&gt;</code> 或 Cookie 携带。<strong>不存在 <code>mfp_</code> PAT、<code>X-API-Key</code> 或 <code>/api/auth/tokens</code>。</strong></p><h2 id="快速试玩-无需登录" tabindex="-1">快速试玩（无需登录） <a class="header-anchor" href="#快速试玩-无需登录" aria-label="Permalink to &quot;快速试玩（无需登录）&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/api/catalog/entities?kind=work&amp;limit=3&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;User-Agent: MyApp/1.0 (you@example.com)&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/api/catalog/entities?q=攻壳机动队&amp;kind=work&amp;limit=3&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;User-Agent: MyApp/1.0 (you@example.com)&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/api/catalog/entities/&lt;id&gt;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;User-Agent: MyApp/1.0 (you@example.com)&quot;</span></span></code></pre></div><h2 id="分页与展开" tabindex="-1">分页与展开 <a class="header-anchor" href="#分页与展开" aria-label="Permalink to &quot;分页与展开&quot;">​</a></h2><ul><li>分页：<code>limit</code>（默认 20）、<code>offset</code>；<code>/api/catalog/entities</code> 另有 <code>kind / type / status / q / field / value / work_id / content_unit_id / release_id / medium_id / parent_id</code></li><li><strong>不存在 <code>inc</code> 展开参数与 <code>page</code> / <code>page_size</code></strong>；响应统一为 JSON</li></ul><h2 id="错误与审计" tabindex="-1">错误与审计 <a class="header-anchor" href="#错误与审计" aria-label="Permalink to &quot;错误与审计&quot;">​</a></h2><ul><li>401：未认证（需写入或模块资源）</li><li>400：参数或 payload 错误</li><li>409：乐观锁版本冲突（写入前需读取当前 <code>version</code>）</li><li>429：命中限流（仅部分路由）</li><li>写入会生成 revision；具体审计范围以技能契约为准，不要假定所有端点都强制 <code>edit_note</code> / <code>source_urls</code></li></ul><p>下一节：<a href="/docs/api-auth">认证与 PAT</a></p>',20)])])}const u=o(d,[["render",c]]);export{h as __pageData,u as default};
